"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { useFieldProps } from "./field";

export interface InputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "size" | "prefix"> {
  size?: "sm" | "md" | "lg";
  /** Icoon of tekst links in het veld. */
  prefix?: React.ReactNode;
  /** Icoon of knop rechts in het veld. */
  suffix?: React.ReactNode;
  /** Vaste tekst tegen het veld aan, bv. ".projectx.be". */
  addon?: React.ReactNode;
  invalid?: boolean;
}

/** Input — tekstveld met optionele iconen, addon en foutstatus. */
export const Input = React.forwardRef<HTMLInputElement, InputProps>(function Input(
  { size = "md", prefix, suffix, addon, invalid, className, ...props },
  ref
) {
  const merged = useFieldProps(props as Parameters<typeof useFieldProps>[0]) as InputProps;
  const { invalid: isInvalid, ...rest } = { ...merged, invalid: invalid ?? (merged as InputProps).invalid };

  const input = (
    <input
      ref={ref}
      className={cn(
        "pxui-input",
        `pxui-input-${size}`,
        prefix && "pxui-input-has-prefix",
        suffix && "pxui-input-has-suffix",
        isInvalid && "pxui-input-invalid",
        !prefix && !suffix && !addon && className
      )}
      aria-invalid={isInvalid || undefined}
      {...(rest as React.InputHTMLAttributes<HTMLInputElement>)}
    />
  );

  if (!prefix && !suffix && !addon) return input;

  return (
    <div
      className={cn(
        "pxui-input-wrap",
        `pxui-input-wrap-${size}`,
        isInvalid && "pxui-input-wrap-invalid",
        className
      )}
    >
      {prefix && <span className="pxui-input-affix pxui-input-prefix">{prefix}</span>}
      {input}
      {suffix && <span className="pxui-input-affix pxui-input-suffix">{suffix}</span>}
      {addon && <span className="pxui-input-addon">{addon}</span>}
    </div>
  );
});

/* ============================ Input ============================ */
.pxui-input {
  width: 100%; height: calc(42px * var(--density)); padding: 0 13px;
  background: var(--surface); color: var(--text);
  border: 1px solid var(--border-strong); border-radius: var(--r-sm);
  font-size: var(--fs-base); outline: none;
  transition: border-color var(--dur-fast), box-shadow var(--dur-fast), background var(--dur-fast);
}
.pxui-input::placeholder { color: var(--text-3); }
.pxui-input:hover:not(:disabled):not(:focus) { border-color: var(--text-3); }
.pxui-input:focus { border-color: var(--accent); box-shadow: var(--ring); }
.pxui-input:disabled { background: var(--surface-3); color: var(--text-2); cursor: not-allowed; }
.pxui-input-invalid { border-color: var(--red); }
.pxui-input-invalid:focus { border-color: var(--red); box-shadow: var(--ring-red); }

.pxui-input-sm { height: calc(34px * var(--density)); padding: 0 10px; font-size: 13px; border-radius: var(--r-xs); }
.pxui-input-lg { height: calc(48px * var(--density)); padding: 0 15px; font-size: var(--fs-md); border-radius: var(--r-md); }

/* ---------- Wrapper met prefix/suffix/addon ---------- */
.pxui-input-wrap {
  position: relative; display: flex; align-items: stretch; width: 100%;
}
.pxui-input-wrap .pxui-input { border-radius: var(--r-sm); }
.pxui-input-wrap-sm .pxui-input { border-radius: var(--r-xs); }
.pxui-input-wrap-lg .pxui-input { border-radius: var(--r-md); }

.pxui-input-affix {
  position: absolute; top: 0; bottom: 0; display: flex; align-items: center;
  color: var(--text-3); pointer-events: none; font-size: 13px;
}
.pxui-input-affix svg { width: 16px; height: 16px; }
.pxui-input-prefix { left: 12px; }
.pxui-input-suffix { right: 12px; pointer-events: auto; }
.pxui-input-has-prefix { padding-left: 36px; }
.pxui-input-has-suffix { padding-right: 36px; }

.pxui-input-wrap .pxui-input-addon {
  display: inline-flex; align-items: center; padding: 0 12px;
  background: var(--surface-3); border: 1px solid var(--border-strong); border-left: none;
  border-radius: 0 var(--r-sm) var(--r-sm) 0;
  color: var(--text-3); font-size: 13px; font-family: var(--mono); white-space: nowrap;
}
.pxui-input-wrap:has(.pxui-input-addon) .pxui-input { border-radius: var(--r-sm) 0 0 var(--r-sm); }
.pxui-input-wrap-invalid .pxui-input-addon { border-color: var(--red); }
